def cantor_numbering(N: int) -> str:
    if N == 1:
        return "1/1"

    layer = 1
    while N > (layer * (layer + 1)) // 2:
        N -= (layer * (layer + 1)) // 2
        layer += 1

    if layer % 2 == 1:
        numerator = 1 + (N - 1)
        denominator = layer - (N - 1)
    else:
        numerator = layer - (N - 1)
        denominator = 1 + (N - 1)

    return f"{numerator}/{denominator}"

