    return sum(count_partitions(n-i, k-1, i) for i in range(x, n//k + 1))

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or n % k != 0:
        return 0
    n -= k * x
    k -= k
    return sum([1 for i in range(1, n // k + 1) for j in range(1, n // k // i + 1) if n // (i * j) == k])

def count_partitions(n: int, k: int, x: int) -> int:
    def helper(n: int, k: int, min_val: int) -> int:
        if k == 0:
            return 1 if n == 0 else 0
        if n < 0 or k < 0:
            return 0
        return sum(helper(n - i, k - 1, max(i, min_val)) for i in range(min_val, n + 1))

    return helper(n, k, x)

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n > last // 2:
        return 0
    if n == 0:
        return 1 if last == 0 else 0
    if last in memo:
        return memo[last]

    count = 0
    for i in range(n + 1, last // 2 + 1):
        count += count_sequences(i, last, memo)

    memo[last] = count
    return count

