def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Dynamic programming approach to solve the 0/1 knapsack problem
    dp = [0] * (T + 1)

    for herb_time, herb_value in herbs:
        for t in range(T, herb_time - 1, -1):
            dp[t] = max(dp[t], dp[t - herb_time] + herb_value)

    return dp[T]

