def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 2:
        return 0

    def find_max_length(heights, is_increasing):
        dp = [1] * n
        for i in range(1, n):
            if (is_increasing and heights[i] > heights[i - 1]) or (not is_increasing and heights[i] < heights[i - 1]):
                dp[i] = dp[i - 1] + 1
        return max(dp)

    increasing = find_max_length(heights, True)
    decreasing = find_max_length(heights[::-1], True)
    max_choir = max(increasing, decreasing) - 1

    return n - max_choir

